package com.theone.cinema;
import android.content.Intent;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class TvNavigationTest {
 @Test public void launcherSearchAndRemoteDetailsWork()throws Exception{UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());Intent i=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);i.putExtra("cinema_test_mode",true);InstrumentationRegistry.getInstrumentation().getTargetContext().startActivity(i);assertTrue(device.wait(Until.hasObject(By.textContains("THE ONE CINEMA")),10000));UiObject2 search=device.findObject(By.res("com.theone.cinema.tv:id/1010"));if(search==null)search=device.findObject(By.clazz("android.widget.EditText"));assertNotNull(search);search.setText("testfilm 3");device.waitForIdle();assertTrue(device.wait(Until.hasObject(By.text("Cinema testfilm 3")),5000));device.findObject(By.text("Cinema testfilm 3")).click();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk")),5000));device.findObject(By.text("▶ Kijk")).click();assertTrue(device.wait(Until.hasObject(By.textContains("180p")),15000));device.pressBack();device.findObject(By.text("Mijn lijst")).click();assertTrue(device.wait(Until.hasObject(By.text("Geen titels gevonden.")),5000));device.findObject(By.text("Films")).click();device.pressDPadDown();device.pressDPadDown();device.pressDPadDown();device.pressDPadRight();device.pressDPadCenter();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk")),5000));device.pressBack();}
}
